select jsonb_build_object(
 'functionDrift',coalesce((select jsonb_agg(e.identity order by e.identity) from expected e left join pg_proc p on p.oid=to_regprocedure(e.identity) where p.oid is null or (e.definition_md5 is not null and md5(pg_get_functiondef(p.oid))<>e.definition_md5) or p.proacl::text is distinct from e.acl or pg_get_userbyid(p.proowner)<>'postgres' or (e.definition_md5 is null and not(p.prorettype='trigger'::regtype and p.prosecdef))),'[]'::jsonb),
 'closedTableDrift',coalesce((select jsonb_agg(t.name order by t.name) from tables t left join pg_namespace n on n.nspname=t.schema_name left join pg_class c on c.relnamespace=n.oid and c.relname=t.name where c.oid is null or c.relacl::text is distinct from t.acl or not c.relrowsecurity or exists(select 1 from pg_policy p where p.polrelid=c.oid)),'[]'::jsonb),
 'trustedSchemas',not exists(select 1 from pg_namespace n where n.nspname in('public','extensions') and(has_schema_privilege('anon',n.oid,'CREATE') or has_schema_privilege('authenticated',n.oid,'CREATE'))),
 'extensionReady',exists(select 1 from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pg_trgm' and e.extversion='1.6' and e.extrelocatable and n.nspname='public') and to_regprocedure('extensions.similarity(text,text)') is null,
 'helpersAbsent',to_regprocedure('public.can_view_story_highlight(uuid)') is null and to_regprocedure('public.can_view_story_highlight_item(uuid,uuid)') is null and to_regprocedure('public.owns_story_highlight_item(uuid,uuid)') is null,
 'oldHighlightPolicies',exists(select 1 from pg_policy where polrelid='public.story_highlights'::regclass and polname='Users can read any highlights' and polcmd='r' and pg_get_expr(polqual,polrelid)='true') and exists(select 1 from pg_policy where polrelid='public.story_highlight_items'::regclass and polname='Users can read highlight items' and polcmd='r' and pg_get_expr(polqual,polrelid)='true')
) preflight;
